      ar:{"T001: قانون النقل":"#d4a017","T002: لوائح التاكسي":"#0891b2","T003: حقوق الركاب":"#7c3aed","T004: قانون السير":"#dc2626","T005: قانون العمل":"#059669","T006: الرقابة الداخلية والسلامة":"#d97706","T007: أشكال الشركات":"#4f46e5","T008: الفهم المالي":"#be123c","T009: الضرائب والرسوم":"#0d9488"},
