      en:{"T1: Road Flow":"#1a9e52","T2: Special Driving Conditions":"#0891b2","T3: Humans in Traffic":"#7c3aed","T4: Vehicle & Legal Requirements":"#d97706","T5: Vehicle Technical":"#dc2626","T6: Passenger Safety":"#0d9488","T7: First Aid & Crisis":"#be123c","T8: Service & Communication":"#4f46e5","T9: Passenger Security":"#059669"},
